mapper.select:
SELECT p.population_id, p.area_code, c.name AS area_name, c.full_name, p.source_code, p.base_date, p.hour, p.total_population, p.male_population, p.female_population, p.male_0_9 AS male0To9, p.male_10_14 AS male10To14, p.male_15_19 AS male15To19, p.male_20_24 AS male20To24, p.male_25_29 AS male25To29, p.male_30_34 AS male30To34, p.male_35_39 AS male35To39, p.male_40_44 AS male40To44, p.male_45_49 AS male45To49, p.male_50_54 AS male50To54, p.male_55_59 AS male55To59, p.male_60_64 AS male60To64, p.male_65_69 AS male65To69, p.male_70_74 AS male70To74, p.female_0_9 AS female0To9, p.female_10_14 AS female10To14, p.female_15_19 AS female15To19, p.female_20_24 AS female20To24, p.female_25_29 AS female25To29, p.female_30_34 AS female30To34, p.female_35_39 AS female35To39, p.female_40_44 AS female40To44, p.female_45_49 AS female45To49, p.female_50_54 AS female50To54, p.female_55_59 AS female55To59, p.female_60_64 AS female60To64, p.female_65_69 AS female65To69, p.female_70_74 AS female70To74, p.metadata::text AS metadata, p.created_at, p.updated_at FROM public.sd_area_population p JOIN public.sd_area_code c ON c.area_code = p.area_code WHERE p.area_code = #{areaCode}
AND p.base_date = #{baseDate}
AND p.hour = #{hour}
ORDER BY p.base_date DESC, p.hour DESC LIMIT 1
